import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"55 - Portfolio Analytics","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/55-portfolio-analytics.md","filePath":"developers/design-documentation/55-portfolio-analytics.md"}'),o={name:"developers/design-documentation/55-portfolio-analytics.md"};function i(r,e,l,d,c,p){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="_55-portfolio-analytics" tabindex="-1">55 - Portfolio Analytics <a class="header-anchor" href="#_55-portfolio-analytics" aria-label="Permalink to &quot;55 - Portfolio Analytics&quot;">​</a></h1><p>Portfolio analytics is an authenticated, synchronous, read-only subsystem. It loads historical prices and, for the Analyzer, current broker holdings. It does not call order placement, modification, or cancellation services.</p><h2 id="request-path" tabindex="-1">Request Path <a class="header-anchor" href="#request-path" aria-label="Permalink to &quot;Request Path&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>React Backtester / Analyzer</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>Flask-RESTX /api/v1/portfolio/*</span></span>
<span class="line"><span>        | schema + API-key/session checks</span></span>
<span class="line"><span>        v</span></span>
<span class="line"><span>services/portfolio_service.py</span></span>
<span class="line"><span>        |</span></span>
<span class="line"><span>        +-- portfolio/data.py -- Historify DuckDB or broker history service</span></span>
<span class="line"><span>        +-- portfolio/engine.py -- allocation, rebalance, turnover, costs</span></span>
<span class="line"><span>        +-- portfolio/analytics.py / attribution.py / grouping.py</span></span>
<span class="line"><span>        +-- portfolio/walkforward.py / compare.py / crisis.py / health.py</span></span>
<span class="line"><span>        +-- openstatz -- statistics and downloadable HTML tearsheet</span></span></code></pre></div><p>The API returns the complete analysis in one response so every results tab reads the same simulation generation.</p><h2 id="data-sources" tabindex="-1">Data Sources <a class="header-anchor" href="#data-sources" aria-label="Permalink to &quot;Data Sources&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Source</th><th>Path</th><th>Operational property</th></tr></thead><tbody><tr><td><code>db</code></td><td>Direct multi-symbol read from Historify DuckDB</td><td>Deterministic and not broker-rate-limited; requires ingestion</td></tr><tr><td><code>api</code></td><td>One history-service call per symbol</td><td>Sequential, rate-limited, and broker/session dependent</td></tr></tbody></table><p>The loader supports NSE/BSE cash instruments. Benchmarks are restricted to <code>NSE_INDEX</code>, <code>BSE_INDEX</code>, and <code>GLOBAL_INDEX</code>; choices come from the active instrument master.</p><p>A process-local, lock-protected LRU cache holds up to 16 loaded price matrices. Historify ingestion clears that cache before newly ingested bars can be observed. <code>HISTORIFY_DATABASE_PATH</code> configures the DuckDB file and defaults to <code>db/historify.duckdb</code>.</p><h2 id="simulation-model" tabindex="-1">Simulation Model <a class="header-anchor" href="#simulation-model" aria-label="Permalink to &quot;Simulation Model&quot;">​</a></h2><ul><li>Long-only and fully invested; weights are normalized and no cash sleeve is modeled.</li><li>A request contains at most 50 unique holdings.</li><li>Missing requested history raises a data error instead of silently changing the portfolio.</li><li>Rebalance rules are <code>never</code>, <code>monthly</code>, <code>quarterly</code>, and <code>yearly</code>; a drift band may trigger between calendar rebalances.</li><li>Costs apply only to realized traded value. The default is an itemized Indian delivery-equity schedule; callers can override components or choose flat basis points. Slippage is separate.</li><li>Returns are price-only. Dividends and user cash flows are not reconstructed.</li></ul><h2 id="analysis-products" tabindex="-1">Analysis Products <a class="header-anchor" href="#analysis-products" aria-label="Permalink to &quot;Analysis Products&quot;">​</a></h2><p>The service serializes equity, benchmark, contribution, correlation, concentration, allocation, costs, and rebalancing data, then adds rolling and drawdown analytics, walk-forward and Monte Carlo robustness, policy comparison, attribution, co-movement structure, crisis windows, a transparent health score, and deterministic findings.</p><p>NaN and infinity become JSON <code>null</code>; keys remain present so the response shape does not silently change when a statistic is undefined.</p><h2 id="current-holdings-adapter" tabindex="-1">Current-Holdings Adapter <a class="header-anchor" href="#current-holdings-adapter" aria-label="Permalink to &quot;Current-Holdings Adapter&quot;">​</a></h2><p>The holdings workflow calls the normalized broker holdings service, parses usable quantity and price fields, and weights assets by current market value. It then runs today&#39;s allocation over historical prices with <code>rebalance=&quot;never&quot;</code>. The response states this counterfactual basis and reports unsupported exchanges separately.</p><h2 id="resource-and-failure-boundaries" tabindex="-1">Resource and Failure Boundaries <a class="header-anchor" href="#resource-and-failure-boundaries" aria-label="Permalink to &quot;Resource and Failure Boundaries&quot;">​</a></h2><ul><li>Backtests are synchronous and hold a full close-price matrix in memory; the 50-symbol cap bounds one request.</li><li>Broker-source runs scale with symbol count and may be slow or rate-limited.</li><li>Missing or incompatible data returns 422; invalid configuration returns 400; authentication/session failures return 403.</li><li>Tearsheet generation has a separate rate limit because embedded-chart rendering is heavier than JSON serialization.</li></ul><p>See <a href="./../../new-features/portfolio-analytics">Portfolio Backtester and Analyzer</a> and the <a href="./../../api-documentation/v1/portfolio">Portfolio API</a>.</p>`,19)])])}const y=a(o,[["render",i]]);export{h as __pageData,y as default};
